package com.ecopassport.model; import jakarta.persistence.*; import java.time.LocalDate; @Entity public class LifecycleEvent{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne Product product; String eventType,location,description; LocalDate eventDate; public Long getId(){return id;} public Product getProduct(){return product;} public void setProduct(Product p){product=p;} public String getEventType(){return eventType;} public String getLocation(){return location;} public String getDescription(){return description;} public LocalDate getEventDate(){return eventDate;} public void setEventDate(LocalDate d){eventDate=d;}}
